"use client"

import type { ReactNode } from "react"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphRule,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type GraphAlign = "left" | "right"

type GraphTableProps = {
  title: string
  headers: string[]
  rows: ReactNode[][]
  footer?: ReactNode[]
  align?: GraphAlign[]
  className?: string
}

function GraphTable({
  title,
  headers,
  rows,
  footer,
  align,
  className,
}: GraphTableProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.04)

  return (
    <Graph title={title} className={className}>
      <GraphBody className="px-3 py-6 sm:px-6 sm:py-8">
        <div className="@container overflow-x-auto">
          <table className="w-full min-w-lg border-separate border-spacing-0">
            <thead>
              <tr>
                {headers.map((header, index) => (
                  <th
                    key={header}
                    className={cn(
                      "px-3 pb-3 font-normal whitespace-nowrap text-foreground",
                      (align?.[index] ?? (index === 0 ? "left" : "right")) ===
                        "right"
                        ? "text-right"
                        : "text-left"
                    )}
                  >
                    {header}
                  </th>
                ))}
              </tr>
              <tr>
                <th colSpan={headers.length} className="p-0">
                  <GraphRule />
                </th>
              </tr>
            </thead>
            <motion.tbody
              initial={reduce ? false : "hidden"}
              variants={list}
              viewport={{ once: true, amount: 0.4 }}
              whileInView="show"
            >
              {rows.map((row, rowIndex) => (
                <motion.tr key={rowIndex} variants={item}>
                  {row.map((cell, cellIndex) => (
                    <td
                      key={cellIndex}
                      className={cn(
                        "px-3 py-2.5 whitespace-nowrap",
                        (align?.[cellIndex] ??
                          (cellIndex === 0 ? "left" : "right")) === "right"
                          ? "text-right tabular-nums"
                          : "text-left"
                      )}
                    >
                      {cell}
                    </td>
                  ))}
                </motion.tr>
              ))}
            </motion.tbody>
            {footer ? (
              <tfoot>
                <tr>
                  <td colSpan={headers.length} className="pt-2 pb-3">
                    <GraphRule />
                  </td>
                </tr>
                <tr>
                  {footer.map((cell, cellIndex) => (
                    <td
                      key={cellIndex}
                      className={cn(
                        "px-3 pt-1 whitespace-nowrap",
                        (align?.[cellIndex] ??
                          (cellIndex === 0 ? "left" : "right")) === "right"
                          ? "text-right tabular-nums"
                          : "text-left"
                      )}
                    >
                      {cell}
                    </td>
                  ))}
                </tr>
              </tfoot>
            ) : null}
          </table>
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphTable }
export type { GraphTableProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type FlowTone = "default" | "accent" | "muted"

type FlowNode = {
  label: string
  tone?: FlowTone
  stretch?: boolean
}

type FlowRow = {
  nodes: FlowNode[]
}

type GraphFlowProps = {
  title: string
  rows: FlowRow[]
  className?: string
}

const toneClass: Record<FlowTone, string> = {
  default: "text-foreground",
  accent: "text-graph-accent",
  muted: "text-graph-muted",
}

function GraphFlow({ title, rows, className }: GraphFlowProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.08)

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col gap-7">
        <motion.div
          className="flex flex-col gap-7"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.5 }}
          whileInView="show"
        >
          {rows.map((row, rowIndex) => (
            <motion.div
              key={rowIndex}
              className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2 sm:flex-nowrap"
              variants={item}
            >
              {row.nodes.map((node, nodeIndex) => {
                const tone = node.tone ?? "default"
                const live = tone === "accent"

                return (
                  <div
                    key={`${node.label}-${nodeIndex}`}
                    className={cn(
                      "flex min-w-0 items-center gap-3",
                      node.stretch && "min-w-16 flex-1"
                    )}
                  >
                    {nodeIndex > 0 ? (
                      <GraphArrow accent={live} stretch={node.stretch} />
                    ) : null}
                    <span
                      className={cn(
                        "shrink-0 whitespace-nowrap",
                        toneClass[tone]
                      )}
                    >
                      {node.label}
                    </span>
                  </div>
                )
              })}
            </motion.div>
          ))}
        </motion.div>
      </GraphBody>
    </Graph>
  )
}

export { GraphFlow }
export type { FlowNode, FlowRow, GraphFlowProps }

"use client"

import type { CSSProperties } from "react"
import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import { graphTransition } from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type BarSeries = {
  label: string
  values: number[]
  size?: "sm" | "lg"
}

type GraphBarsProps = {
  title: string
  from: BarSeries
  to: BarSeries
  processor?: string
  className?: string
}

function MiniBars({
  values,
  size = "sm",
  delay = 0,
  tone = "accent",
}: {
  values: number[]
  size?: "sm" | "lg"
  delay?: number
  tone?: "accent" | "muted"
}) {
  const reduce = useReducedMotion()
  const max = Math.max(...values, 1)
  const maxHeight = size === "lg" ? 56 : 28
  const barWidth = size === "lg" ? 10 : 5

  return (
    <div className="flex items-end gap-px">
      {values.map((value, index) => (
        <motion.span
          key={index}
          className={cn(
            "block h-(--bar-h) w-(--bar-w) origin-bottom will-change-transform",
            tone === "accent" ? "bg-graph-accent" : "bg-graph-frame"
          )}
          initial={reduce ? false : { transform: "scaleY(0.08)" }}
          style={
            {
              "--bar-h": `${Math.max((value / max) * maxHeight, 2)}px`,
              "--bar-w": `${barWidth}px`,
            } as CSSProperties
          }
          transition={graphTransition(reduce, { delay: delay + index * 0.04 })}
          viewport={{ once: true, amount: 0.6 }}
          whileInView={{ transform: "scaleY(1)" }}
        />
      ))}
    </div>
  )
}

function GraphBars({
  title,
  from,
  to,
  processor = "AI",
  className,
}: GraphBarsProps) {
  return (
    <Graph title={title} className={className}>
      <GraphBody>
        <div className="flex flex-col items-center gap-8 sm:flex-row sm:items-end sm:justify-between sm:gap-4">
          <div className="flex flex-col items-center gap-3">
            <MiniBars
              delay={0.04}
              size={from.size ?? "sm"}
              tone="muted"
              values={from.values}
            />
            <p className="text-graph-muted">{from.label}</p>
          </div>

          <div className="flex items-center gap-3 text-graph-muted max-sm:rotate-90">
            <GraphArrow />
            <span>{processor}</span>
            <GraphArrow />
          </div>

          <div className="flex flex-col items-center gap-3">
            <MiniBars delay={0.16} size={to.size ?? "lg"} values={to.values} />
            <p className="text-foreground">{to.label}</p>
          </div>
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphBars }
export type { BarSeries, GraphBarsProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fillDelay,
  graphTransition,
} from "@/registry/default/graph-frame/graph-motion"

type CellGrid = {
  label: string
  cells: number[][]
}

type GraphCellsProps = {
  title: string
  items: CellGrid[]
  className?: string
}

function Cell({ filled, delay }: { filled: boolean; delay: number }) {
  const reduce = useReducedMotion()

  return (
    <span className="relative size-2.5 shrink-0">
      <span
        aria-hidden="true"
        className="absolute inset-0 border border-graph-frame"
      />
      {filled ? (
        <motion.span
          aria-hidden="true"
          className="absolute inset-0 bg-graph-accent will-change-[opacity]"
          initial={reduce ? false : { opacity: 0 }}
          transition={graphTransition(reduce, { delay })}
          viewport={{ once: true }}
          whileInView={{ opacity: 1 }}
        />
      ) : null}
    </span>
  )
}

function GraphCells({ title, items, className }: GraphCellsProps) {
  const reduce = useReducedMotion()

  return (
    <Graph title={title} className={className}>
      <GraphBody>
        <div className="@container flex flex-col items-center justify-center gap-10 @min-[28rem]:flex-row @min-[28rem]:gap-12">
          {items.map((item, itemIndex) => (
            <div key={item.label} className="flex flex-col items-center gap-4">
              <div className="flex flex-col gap-1">
                {item.cells.map((row, rowIndex) => (
                  <div key={rowIndex} className="flex gap-1">
                    {row.map((cell, cellIndex) => (
                      <Cell
                        key={cellIndex}
                        delay={fillDelay(
                          reduce,
                          itemIndex * 8 + rowIndex * 5 + cellIndex
                        )}
                        filled={cell === 1}
                      />
                    ))}
                  </div>
                ))}
              </div>
              <p className="text-graph-muted">{item.label}</p>
            </div>
          ))}
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphCells }
export type { CellGrid, GraphCellsProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type ScaleItem = {
  ratio: string
  label: string
  token: "14" | "23" | "45" | "70"
  accent?: boolean
}

type GraphScaleProps = {
  title: string
  items: ScaleItem[]
  className?: string
}

const tokenClass: Record<ScaleItem["token"], string> = {
  "14": "text-contrast-14",
  "23": "text-contrast-23",
  "45": "text-contrast-45",
  "70": "text-contrast-70",
}

function GraphScale({ title, items, className }: GraphScaleProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)

  return (
    <Graph title={title} className={className}>
      <GraphBody>
        <motion.ul
          role="list"
          className="flex flex-col gap-3"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.5 }}
          whileInView="show"
