          {items.map((entry) => (
            <motion.li
              key={entry.ratio}
              className="grid grid-cols-[5.5rem_1fr] items-baseline gap-6"
              variants={item}
            >
              <span
                className={cn(
                  "tabular-nums",
                  entry.accent ? "text-graph-accent" : tokenClass[entry.token]
                )}
              >
                {entry.ratio}
              </span>
              <span className={tokenClass[entry.token]}>{entry.label}</span>
            </motion.li>
          ))}
        </motion.ul>
      </GraphBody>
    </Graph>
