}

export { GraphScale }
export type { GraphScaleProps, ScaleItem }

"use client"

import type { CSSProperties } from "react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import { cn } from "@/lib/utils"

const OUTER = 16
const INSET = 4

type GraphRadiiProps = {
  title?: string
  outer?: number
  inset?: number
  className?: string
}

function CornerMark({
  className,
  radius,
}: {
  className: string
  radius: number
}) {
  return (
    <span
      aria-hidden="true"
      className={cn("pointer-events-none absolute size-5", className)}
      style={{ borderRadius: `${radius}px` }}
    />
  )
}

function GraphRadii({
  title = "NESTED RADII",
  outer = OUTER,
  inset = INSET,
  className,
}: GraphRadiiProps) {
  const inner = outer - inset

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col items-center gap-6">
        <div
          className="relative w-full max-w-72"
          style={
            {
              "--outer": `${outer}px`,
              "--inset": `${inset}px`,
            } as CSSProperties
          }
        >
          <div
            className="relative border border-dashed border-graph-frame p-(--inset)"
            style={{ borderRadius: "var(--outer)" }}
          >
            <CornerMark
              className="top-0 left-0 border-t-2 border-l-2 border-graph-accent"
              radius={outer}
            />
            <CornerMark
              className="top-0 right-0 border-t-2 border-r-2 border-graph-accent"
              radius={outer}
            />
            <CornerMark
              className="bottom-0 left-0 border-b-2 border-l-2 border-graph-accent"
              radius={outer}
            />
            <CornerMark
              className="right-0 bottom-0 border-r-2 border-b-2 border-graph-accent"
              radius={outer}
            />

            <div
              className="relative flex min-h-48 flex-col items-center justify-center gap-3 border border-dashed border-graph-frame px-4 py-12"
              style={{
                borderRadius: `calc(var(--outer) - var(--inset))`,
              }}
            >
              <CornerMark
                className="top-0 left-0 border-t-2 border-l-2 border-graph-accent"
                radius={inner}
              />
              <CornerMark
                className="top-0 right-0 border-t-2 border-r-2 border-graph-accent"
                radius={inner}
              />
              <CornerMark
                className="bottom-0 left-0 border-b-2 border-l-2 border-graph-accent"
                radius={inner}
              />
              <CornerMark
                className="right-0 bottom-0 border-r-2 border-b-2 border-graph-accent"
                radius={inner}
              />
              <p className="text-foreground">outer {outer}px</p>
              <p className="text-foreground">inner {inner}px</p>
              <p className="text-graph-muted">
                <span aria-hidden="true">| ◀ - ▶ |</span> inset {inset}px
              </p>
            </div>
          </div>
        </div>

        <p className="text-center text-graph-muted">inner = outer − inset</p>
        <p className="text-center text-foreground tabular-nums">
          {inner}px = {outer}px − {inset}px
        </p>
      </GraphBody>
    </Graph>
  )
}

export { GraphRadii }
export type { GraphRadiiProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  fillDelay,
  graphTransition,
} from "@/registry/default/graph-frame/graph-motion"

type GraphMeterProps = {
  title: string
  value: number
  ticks?: number
  caption?: string
  className?: string
}

function GraphMeter({
  title,
  value,
  ticks = 14,
  caption,
  className,
}: GraphMeterProps) {
  const reduce = useReducedMotion()
  const clamped = Math.min(1, Math.max(0, value))
  const filled = Math.round(clamped * ticks)

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col items-center gap-4">
        <p className="flex items-center gap-3 tabular-nums">
          <span aria-hidden="true" className="text-graph-frame select-none">
            [
          </span>
          <span className="flex select-none" aria-hidden="true">
            {Array.from({ length: ticks }, (_, index) => {
              const isFilled = index < filled

              return (
                <motion.span
                  key={index}
                  className={
                    isFilled ? "text-graph-accent" : "text-graph-frame"
                  }
                  initial={reduce || !isFilled ? false : { opacity: 0 }}
                  transition={graphTransition(reduce, {
                    delay: fillDelay(reduce, index),
                  })}
                  viewport={{ once: true }}
                  whileInView={{ opacity: 1 }}
                >
                  {isFilled ? "=" : "-"}
                </motion.span>
              )
            })}
          </span>
          <span aria-hidden="true" className="text-graph-frame select-none">
            ]
          </span>
          <span className="w-[4ch] text-right text-graph-accent">
            {Math.round(clamped * 100)}%
          </span>
        </p>
        {caption ? <p className="text-graph-muted">{caption}</p> : null}
        <span className="sr-only">
          {Math.round(clamped * 100)} percent
          {caption ? ` ${caption}` : ""}
        </span>
      </GraphBody>
    </Graph>
  )
}

export { GraphMeter }
export type { GraphMeterProps }

"use client"

import { motion, useReducedMotion } from "motion/react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import {
  DIM_OPACITY,
  fillDelay,
  graphTransition,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

const GLYPHS = "▁▂▃▄▅▆▇█"

type GraphSparkProps = {
  title: string
  data: number[]
  caption?: string
  className?: string
}

function GraphSpark({ title, data, caption, className }: GraphSparkProps) {
  const reduce = useReducedMotion()
  const max = Math.max(...data, 1)
  const last = data.length - 1
  const glyphs = data.map((value) => {
    const index = Math.round((value / max) * (GLYPHS.length - 1))
    return GLYPHS[index]
  })

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col items-center gap-4">
        <p className="flex select-none" aria-hidden="true">
          {glyphs.map((glyph, index) => {
            const live = index === last

            return (
              <motion.span
                key={`${glyph}-${index}`}
                className={cn(
                  "inline-block w-[1ch] text-center",
                  live ? "text-graph-accent" : "text-graph-muted"
                )}
                initial={reduce ? false : { opacity: 0 }}
                transition={graphTransition(reduce, {
                  delay: fillDelay(reduce, index),
                })}
                viewport={{ once: true }}
                whileInView={{ opacity: live ? 1 : DIM_OPACITY }}
              >
                {glyph}
              </motion.span>
            )
          })}
        </p>
        {caption ? <p className="text-graph-muted">{caption}</p> : null}
        <span className="sr-only">
          Sparkline with {data.length} points
          {caption ? `. ${caption}` : ""}
        </span>
      </GraphBody>
    </Graph>
  )
}

export { GraphSpark }
