type GraphPlotProps = {
  title: string
  data: number[]
  labels?: string[]
  height?: number
  variant?: "line" | "area"
  progress?: number
  className?: string
}

function formatTick(value: number) {
  if (Number.isInteger(value)) {
    return String(value)
  }

  return value.toFixed(1)
}

function GraphPlot({
  title,
  data,
  labels,
  height = 7,
  variant = "area",
  progress = 1,
  className,
}: GraphPlotProps) {
  const reduce = useReducedMotion()
  const max = Math.max(...data, 0)
  const min = Math.min(0, ...data)
  const range = max - min || 1
  const end = labels?.[labels.length - 1]
  const start = labels?.[0]
  const yLabel = formatTick(max)
  const revealed = Math.round(clamp01(progress) * data.length)
  const lastLive = Math.max(0, revealed - 1)

  return (
    <Graph title={title} className={className}>
      <GraphBody className="flex flex-col gap-3 overflow-x-auto">
        <div className="flex gap-3">
          <div
            className="flex w-[4ch] shrink-0 flex-col justify-between py-px text-right text-graph-muted tabular-nums"
            style={{ height: `${height}em` }}
          >
            <span>{yLabel}</span>
            <span>{formatTick(min)}</span>
          </div>
          <div
            aria-hidden="true"
            className="flex min-w-0 items-end gap-px select-none"
            style={{ height: `${height}em` }}
          >
            {data.map((value, column) => {
              const level = Math.round(((value - min) / range) * (height - 1))
              const live = column === lastLive && column < revealed
              const shown = column < revealed

              return (
                <span className="flex h-full flex-col justify-end" key={column}>
                  {Array.from({ length: height }, (_, row) => {
                    const fromBottom = height - 1 - row
                    const isCap = shown && fromBottom === level
                    const isFill =
                      shown && variant === "area" && fromBottom < level
                    const glyph = isCap ? "█" : isFill ? "░" : " "
                    const tone = isCap
                      ? live
                        ? "text-graph-accent"
                        : "text-foreground"
                      : isFill
                        ? "text-graph-muted"
                        : "text-transparent"

                    return (
                      <motion.span
                        className={cn("h-[1em] w-[1ch] text-center", tone)}
                        initial={
                          reduce || !shown || glyph === " "
                            ? false
                            : { opacity: 0 }
                        }
                        key={row}
                        transition={graphTransition(reduce, {
                          delay: fillDelay(reduce, column),
                        })}
                        viewport={{ once: true }}
                        whileInView={{ opacity: 1 }}
                      >
                        {glyph}
                      </motion.span>
                    )
                  })}
                </span>
              )
            })}
          </div>
        </div>
        {start || end ? (
          <>
            <div className="flex gap-3">
              <span className="invisible w-[4ch] shrink-0 tabular-nums">
                {yLabel}
              </span>
              <GraphRule className="flex-1" />
            </div>
            <div className="flex gap-3">
              <span className="invisible w-[4ch] shrink-0 tabular-nums">
                {yLabel}
              </span>
              <div className="flex flex-1 justify-between text-graph-muted">
                <span>{start}</span>
                {end && end !== start ? <span>{end}</span> : null}
              </div>
            </div>
          </>
        ) : null}
        <span className="sr-only">
          {variant} plot, {data.length} points, min {formatTick(min)}, max{" "}
          {formatTick(max)}
        </span>
      </GraphBody>
    </Graph>
  )
}

